import { Effect, Schema } from "effect";
import { AnthropicMessages } from "../protocols/anthropic-messages.js";
import { MiniMaxImages } from "../protocols/minimax-images.js";
import { MiniMaxVideo } from "../protocols/minimax-video.js";
import { OpenAIChat } from "../protocols/openai-chat.js";
import { OpenResponses } from "../protocols/open-responses.js";
import { ProviderShared } from "../protocols/shared.js";
import { Route } from "../route/client.js";
import { Endpoint } from "../route/endpoint.js";
import { Framing } from "../route/framing.js";
import { MediaRoute } from "../route/media.js";
import { Protocol } from "../route/protocol.js";
import { ProviderID, } from "../schema/index.js";
import { bearerRouteDefaults, toConfig } from "./settings.js";
export const id = ProviderID.make("minimax");
const ChatOptions = Schema.Struct({
    thinking: Schema.optional(Schema.Struct({ type: Schema.String })),
    reasoningSplit: Schema.optional(Schema.Boolean),
});
const chatProtocol = Protocol.make({
    id: "minimax-chat",
    body: {
        schema: Schema.Struct({
            ...OpenAIChat.bodyFields,
            thinking: ChatOptions.fields.thinking,
            reasoning_split: Schema.Boolean,
        }),
        from: Effect.fn("MiniMax.chatFromRequest")(function* (request) {
            const options = yield* ProviderShared.validateWith(Schema.decodeUnknownEffect(ChatOptions))(request.providerOptions ?? {});
            return {
                ...(yield* OpenAIChat.protocol.body.from(request)),
                thinking: options.thinking,
                // MiniMax otherwise embeds <think> tags in ordinary assistant text.
                reasoning_split: options.reasoningSplit ?? true,
            };
        }),
    },
    stream: OpenAIChat.protocol.stream,
});
const messagesRoute = Route.make({
    id: "minimax-messages",
    provider: id,
    providerMetadataKey: "minimax",
    protocol: AnthropicMessages.protocol,
    endpoint: Endpoint.path("/messages", { baseURL: "https://api.minimax.io/anthropic/v1" }),
    framing: AnthropicMessages.framing,
    headers: () => ({ "anthropic-version": "2023-06-01" }),
});
const chatRoute = Route.make({
    id: "minimax-chat",
    provider: id,
    providerMetadataKey: "minimax",
    protocol: chatProtocol,
    endpoint: Endpoint.path("/chat/completions", { baseURL: "https://api.minimax.io/v1" }),
    framing: OpenAIChat.framing,
});
const responsesRoute = Route.make({
    id: "minimax-responses",
    provider: id,
    providerMetadataKey: "minimax",
    protocol: OpenResponses.protocol,
    endpoint: Endpoint.path("/responses", { baseURL: "https://api.minimax.io/v1" }),
    framing: Framing.sse,
});
export const routes = [messagesRoute, chatRoute, responsesRoute];
export const configure = (input = {}) => {
    const defaults = bearerRouteDefaults(input, "MINIMAX_API_KEY");
    const messages = (modelID) => messagesRoute.with(defaults).model({
        id: modelID,
        compatibility: { requireSignature: false },
    });
    const chat = (modelID) => chatRoute.with(defaults).model({
        id: modelID,
        capabilities: { tools: { strict: false } },
    });
    const responses = (modelID) => responsesRoute.with(defaults).model({ id: modelID });
    const media = MediaRoute.deployment(input, defaults.auth);
    const image = (modelID, providerOptions) => MiniMaxImages.model({ ...media, id: modelID, providerOptions });
    // H3 is under /v2 and Hailuo under /v1, so video drops the version a shared `baseURL` carries for the other APIs.
    const videoBaseURL = media.baseURL?.replace(/(\/v1)?\/*$/, "");
    const video = (modelID, providerOptions) => MiniMaxVideo.model({ ...media, baseURL: videoBaseURL, id: modelID, providerOptions });
    return { id, model: messages, messages, chat, responses, image, video, configure };
};
export const provider = configure();
export const model = (modelID, settings) => configure(toConfig(settings)).model(modelID);
export const imageModel = (modelID, settings) => {
    const input = toConfig(settings);
    return configure(input).image(modelID, input.providerOptions);
};
export const videoModel = (modelID, settings) => {
    const input = toConfig(settings);
    return configure(input).video(modelID, input.providerOptions);
};
export const messages = provider.messages;
export const chat = provider.chat;
export const responses = provider.responses;
export const image = provider.image;
export const video = provider.video;
export * as MiniMax from "./minimax.js";
